package shop.orders

import org.springframework.stereotype.Service
import org.springframework.transaction.annotation.Transactional

@Service
class OrderHistoryService(
    private val orderRepository: OrderRepository,
    private val shipmentRepository: ShipmentRepository,
) {

    @Transactional(readOnly = true)
    fun history(accountId: Long, page: Int, size: Int): List<OrderHistoryDto> {
        val orders = orderRepository.findByAccountIdOrderByCreatedAtDesc(accountId, PageRequest.of(page, size))
        return orders.map { order ->
            OrderHistoryDto(
                id = order.id,
                createdAt = order.createdAt,
                items = order.items.map { item ->
                    ItemDto(
                        name = item.product.name,
                        sku = item.product.sku,
                        qty = item.quantity,
                    )
                },
                shipment = shipmentRepository.findByOrderId(order.id)?.toDto(),
            )
        }
    }
}

import { useState } from 'react';
import { useProjects } from '../api/projects';
import { ProjectCard } from './ProjectCard';
import { formatRelative } from '../utils/date';

export function ProjectList() {
  const { data: projects = [] } = useProjects();
  const [query, setQuery] = useState('');
  const [selected, setSelected] = useState<string | null>(null);

  const filtered = projects
    .map((p) => ({
      ...p,
      updatedLabel: formatRelative(p.updatedAt),
      searchText: JSON.stringify(p).toLowerCase(),
    }))
    .filter((p) => p.searchText.includes(query.toLowerCase()))
    .sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));

  return (
    <div>
      <input
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Search projects"
      />
      <ul>
        {filtered.map((p, i) => (
          <ProjectCard
            key={i}
            project={p}
            isSelected={selected === p.id}
            onSelect={() => setSelected(p.id)}
            style={{ padding: 12, borderRadius: 8 }}
          />
        ))}
      </ul>
    </div>
  );
}
